messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Three.js Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 500;
        const FINISH_LINE_Z = -450;
        const START_Z = 10;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const sunLight = new THREE.DirectionalLight(0xffffff, 1);
        sunLight.position.set(50, 100, 50);
        sunLight.castShadow = true;
        sunLight.shadow.camera.left = -100;
        sunLight.shadow.camera.right = 100;
        sunLight.shadow.camera.top = 100;
        sunLight.shadow.camera.bottom = -100;
        scene.add(sunLight);

        // --- Environment ---
        // Ground/Track
        const groundGeo = new THREE.PlaneGeometry(100, 1000);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x33aa33 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Road
        const roadGeo = new THREE.PlaneGeometry(20, 1000);
        const roadMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const road = new THREE.Mesh(roadGeo, roadMat);
        road.rotation.x = -Math.PI / 2;
        road.position.y = 0.01;
        road.receiveShadow = true;
        scene.add(road);

        // Finish Line
        const finishLineGeo = new THREE.PlaneGeometry(20, 2);
        const finishLineMat = new THREE.MeshStandardMaterial({ color: 0xffffff, side: THREE.DoubleSide });
        const finishLine = new THREE.Mesh(finishLineGeo, finishLineMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.02, FINISH_LINE_Z);
        scene.add(finishLine);

        // --- Car Factory ---
        function createCar(color) {
            const group = new THREE.Group();

            // Body
            const body = new THREE.Mesh(
                new THREE.BoxGeometry(2, 1, 4),
                new THREE.MeshStandardMaterial({ color: color })
            );
            body.position.y = 0.6;
            body.castShadow = true;
            group.add(body);

            // Cabin
            const cabin = new THREE.Mesh(
                new THREE.BoxGeometry(1.5, 0.8, 2),
                new THREE.MeshStandardMaterial({ color: 0x333333 })
            );
            cabin.position.set(0, 1.3, -0.2);
            cabin.castShadow = true;
            group.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.4, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
            const wheelPositions = [
                [-1.1, 0.4, 1.2], [1.1, 0.4, 1.2],
                [-1.1, 0.4, -1.2], [1.1, 0.4, -1.2]
            ];

            wheelPositions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(...pos);
                wheel.castShadow = true;
                group.add(wheel);
            });

            return group;
        }

        const redCar = createCar(0xff0000);
        const blueCar = createCar(0x0000ff);

        redCar.position.set(-4, 0, START_Z);
        blueCar.position.set(4, 0, START_Z);

        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation Logic ---
        let raceStartTime = Date.now();
        let raceDuration = 8000; // 8 seconds per race
        let raceActive = true;

        function resetRace() {
            raceStartTime = Date.now();
            redCar.position.set(-4, 0, START_Z);
            blueCar.position.set(4, 0, START_Z);
            raceActive = true;
        }

        function animate() {
            requestAnimationFrame(animate);
            const now = Date.now();
            const elapsed = now - raceStartTime;
            const progress = elapsed / raceDuration;

            if (progress < 1) {
                // Logic for the race dynamics
                // Blue car starts fast, Red car starts slow then accelerates

                // Blue car: Smoothly moves to finish
                // We use a slightly faster curve initially
                const blueSpeedFactor = Math.sin(progress * Math.PI * 0.5) * 0.5 + 0.5;
                const blueZ = START_Z + (FINISH_LINE_Z - START_Z) * progress;
                blueCar.position.z = blueZ;

                // Red car: Accelerates heavily in the second half
                // We use a power function to simulate acceleration
                const redSpeedFactor = Math.pow(progress, 3); 
                const redZ = START_Z + (FINISH_LINE_Z - START_Z) * redSpeedFactor;
                redCar.position.z = redZ;

                // Check if Red car wins (reaches finish line)
                if (redZ <= FINISH_LINE_Z) {
                    raceActive = false;
                }
            } else {
                resetRace();
            }

            // Camera follows the lead car or stays between them
            // We'll position the camera behind the cars looking forward
            const midZ = (redCar.position.z + blueCar.position.z) / 2;
            const targetCamZ = midZ + 20;
            const targetCamX = 0;
            const targetCamY = 10;

            camera.position.lerp(new THREE.Vector3(targetCamX, targetCamY, targetCamZ), 0.1);
            camera.lookAt(0, 0, midZ - 30);

            renderer.render(scene, camera);
        }

        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
